#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

static i128 sq(i128 x) { return x * x; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 w, h, p, q, x, y, v, t;
    cin >> w >> h >> p >> q >> x >> y >> v >> t;

    // In the unfolded plane, reflected paths correspond to straight lines
    // from (x,y) to mirrored images of (p,q):
    // (±p + 2kw, ±q + 2lh)
    // Count how many such image points are within distance <= v*t.
    i128 R2 = sq((i128)v * t);

    // Safe search bounds.
    // Need |image_x - x| <= v*t and |image_y - y| <= v*t.
    // Since image_x = s*p + 2kw (s = ±1), k lies in a bounded interval.
    i128 R = (i128)v * t;

    auto floordiv = [](i128 a, i128 b) -> i128 {
        // b > 0
        if (a >= 0) return a / b;
        return - ((-a + b - 1) / b);
    };
    auto ceildiv = [&](i128 a, i128 b) -> i128 {
        // b > 0
        return -floordiv(-a, b);
    };

    long long ans = 0;

    for (int sx : {-1, 1}) {
        i128 baseX = (i128)sx * p;
        i128 lowK = ceildiv((i128)x - R - baseX, (i128)2 * w);
        i128 highK = floordiv((i128)x + R - baseX, (i128)2 * w);

        for (i128 k = lowK; k <= highK; ++k) {
            i128 X = baseX + (i128)2 * w * k;
            i128 dx = X - x;
            i128 rem = R2 - dx * dx;
            if (rem < 0) continue;

            for (int sy : {-1, 1}) {
                i128 baseY = (i128)sy * q;

                // Need (baseY + 2lh - y)^2 <= rem
                // We avoid sqrt by just bounding l with |...| <= R, which is safe,
                // then checking exact squared distance.
                i128 lowL = ceildiv((i128)y - R - baseY, (i128)2 * h);
                i128 highL = floordiv((i128)y + R - baseY, (i128)2 * h);

                for (i128 l = lowL; l <= highL; ++l) {
                    i128 Y = baseY + (i128)2 * h * l;
                    i128 dy = Y - y;
                    if (dx * dx + dy * dy <= R2) ++ans;
                }
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

#include <stdio.h>
#include <math.h>

int main() {
    int w, h;
    double p, q, x, y, v, t;
    scanf("%d %d", &w, &h);
    scanf("%lf %lf", &p, &q);
    scanf("%lf %lf", &x, &y);
    scanf("%lf %lf", &v, &t);

    double max_dist = v * t;
    double max_dist_sq = max_dist * max_dist;

    int count = 0;

    // We need to consider enough reflections so that the distance can be <= max_dist.
    // The maximum number of reflections needed in each direction:
    int max_reflect_x = (int)(max_dist / w) + 2;
    int max_reflect_y = (int)(max_dist / h) + 2;

    for (int rx = -max_reflect_x; rx <= max_reflect_x; ++rx) {
        // Mirrored x coordinate
        double mx;
        if (rx % 2 == 0) {
            mx = rx * w + p;
        } else {
            mx = rx * w + (w - p);
        }

        double dx = mx - x;
        double dx_sq = dx * dx;

        for (int ry = -max_reflect_y; ry <= max_reflect_y; ++ry) {
            double my;
            if (ry % 2 == 0) {
                my = ry * h + q;
            } else {
                my = ry * h + (h - q);
            }

            double dy = my - y;
            double dist_sq = dx_sq + dy * dy;

            if (fabs(dist_sq - max_dist_sq) < 1e-9) {
                count++;
            }
        }
    }

    printf("%d\n", count);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main() {
    double w, h, p, q, x, y, v, t;
    while (scanf("%lf %lf %lf %lf %lf %lf %lf %lf", &w, &h, &p, &q, &x, &y, &v, &t) == 8) {
        double R = v * t;
        long long count = 0;
        // 4 sign combinations for reflections
        double eps_x[] = {1.0, -1.0};
        double eps_y[] = {1.0, -1.0};
        for (int sx = 0; sx < 2; sx++) {
            double dx0 = eps_x[sx] * p - x;
            for (int sy = 0; sy < 2; sy++) {
                double dy0 = eps_y[sy] * q - y;
                // iterate k
                long long kmin = (long long)floor((-R - dx0) / (2*w));
                long long kmax = (long long)ceil((R - dx0) / (2*w));
                for (long long k = kmin; k <= kmax; k++) {
                    double dx = 2.0*k*w + dx0;
                    if (dx*dx > R*R + 1e-9) continue;
                    double rem = sqrt(R*R - dx*dx);
                    long long mmin = (long long)floor((-rem - dy0) / (2*h));
                    long long mmax = (long long)ceil((rem - dy0) / (2*h));
                    for (long long m = mmin; m <= mmax; m++) {
                        double dy = 2.0*m*h + dy0;
                        double dist2 = dx*dx + dy*dy;
                        if (dist2 <= R*R + 1e-9) count++;
                    }
                }
            }
        }
        // Correct for duplicates when p=0,w or q=0,h
        // eps_x*p same for both signs when p=0; divide count by 2
        if (fabs(p) < 1e-9 || fabs(p - w) < 1e-9) count /= 2;
        if (fabs(q) < 1e-9 || fabs(q - h) < 1e-9) count /= 2;
        printf("%lld\n", count);
    }
    return 0;
}

