typedef long long ll;

static ll floor_div_ll(ll a, ll b) {
    // b > 0
    if (a >= 0) return a / b;
    return -(( -a + b - 1) / b);
}

static ll ceil_div_ll(ll a, ll b) {
    // b > 0
    if (a >= 0) return (a + b - 1) / b;
    return -((-a) / b);
}

static ll isqrt_ll(ll n) {
    if (n <= 0) return 0;
    long double d = sqrt((long double)n);
    ll x = (ll)d;
    while ((__int128)(x + 1) * (x + 1) <= n) x++;
    while ((__int128)x * x > n) x--;
    return x;
}

int main(void) {
    ll w, h, p, q, x, y, v, t;
    if (scanf("%lld %lld %lld %lld %lld %lld %lld %lld",
              &w, &h, &p, &q, &x, &y, &v, &t) != 8) {
        return 0;
    }

    ll R = v * t;                 // maximum travel distance
    ll R2 = R * R;
    ll ans = 0;

    // By unfolding reflections, targets appear at:
    // X = 2kw ± p, Y = 2lh ± q
    // Count integer pairs satisfying (X-x)^2 + (Y-y)^2 = d^2 <= R^2

    ll maxK = R / w + 3;

    for (int sx = -1; sx <= 1; sx += 2) {
        ll baseX = sx * p - x; // dx = 2kw + baseX

        ll kmin = ceil_div_ll(-R - baseX, 2 * w);
        ll kmax = floor_div_ll(R - baseX, 2 * w);

        for (ll k = kmin; k <= kmax; k++) {
            ll dx = 2 * k * w + baseX;
            ll dx2 = dx * dx;
            if (dx2 > R2) continue;

            ll rem = R2 - dx2;
            ll s = isqrt_ll(rem);

            for (int sy = -1; sy <= 1; sy += 2) {
                ll baseY = sy * q - y; // dy = 2lh + baseY

                // Need |dy| <= s
                ll lmin = ceil_div_ll(-s - baseY, 2 * h);
                ll lmax = floor_div_ll(s - baseY, 2 * h);

                for (ll l = lmin; l <= lmax; l++) {
                    ll dy = 2 * l * h + baseY;
                    if (dx2 + dy * dy <= R2) ans++;
                }
            }
        }
    }

    printf("%lld\n", ans);
    return 0;
}

