public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().trim().split(" ");
        double w = Double.parseDouble(parts[0]);
        double h = Double.parseDouble(parts[1]);
        double v = Double.parseDouble(parts[2]);
        double t = Double.parseDouble(parts[3]);
        parts = br.readLine().trim().split(" ");
        double p = Double.parseDouble(parts[0]);
        double q = Double.parseDouble(parts[1]);
        parts = br.readLine().trim().split(" ");
        double x = Double.parseDouble(parts[0]);
        double y = Double.parseDouble(parts[1]);

        // maximum distance shockwave can travel
        double R = v * t;

        // We consider all reflected images of the enemy (p,q) in the infinite grid
        // Each image is at (px, py) where px = ±p + 2*a*w, py = ±q + 2*b*h
        // We count how many images lie within distance R from (x,y)

        long count = 0;

        // Estimate bounds for reflections
        // We need to check reflections up to distance R from (x,y)
        // The furthest image coordinate difference is roughly R, so number of reflections
        // in each dimension is about ceil(R / (2*w)) + 1, similarly for h.

        long maxA = (long)Math.ceil((R + Math.abs(x) + Math.abs(p)) / (2 * w)) + 2;
        long maxB = (long)Math.ceil((R + Math.abs(y) + Math.abs(q)) / (2 * h)) + 2;

        // We'll iterate over all image positions in the bounded range
        for (long a = -maxA; a <= maxA; a++) {
            for (int sx = -1; sx <= 1; sx += 2) { // sign for p
                double px = sx * p + 2 * a * w;
                double dx = px - x;
                if (Math.abs(dx) > R) continue; // early prune
                for (long b = -maxB; b <= maxB; b++) {
                    for (int sy = -1; sy <= 1; sy += 2) { // sign for q
                        double py = sy * q + 2 * b * h;
                        double dy = py - y;
                        double distSq = dx * dx + dy * dy;
                        if (distSq <= R * R + 1e-12) {
                            count++;
                        }
                    }
                }
            }
        }

        System.out.println(count);
    }
}

