public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static long floorDiv(long a, long b) {
        // b > 0
        if (a >= 0) return a / b;
        return -(( -a + b - 1) / b);
    }

    static long ceilDiv(long a, long b) {
        // b > 0
        if (a >= 0) return (a + b - 1) / b;
        return -((-a) / b);
    }

    static long countSolutions(long A, long B, long C, long D) {
        // Count integer pairs (m, n) such that:
        // A*m + B*n = 0
        // C*m + D*n = 0
        // Here actually used only for one linear equation:
        return 0;
    }

    static long countForTarget(long dx0, long dy0, long W, long H, long R2) {
        // Count integer pairs (k,l) with:
        // (dx0 + 2W*k)^2 + (dy0 + 2H*l)^2 <= R2
        // where dx0,dy0 are one of mirrored offsets.
        long ans = 0;

        if (W == 0 && H == 0) {
            return (dx0 * dx0 + dy0 * dy0 <= R2) ? 1 : 0;
        }

        if (W == 0) {
            long x2 = dx0 * dx0;
            if (x2 > R2) return 0;
            long rem = R2 - x2;
            long maxY = isqrt(rem);
            long low = ceilDiv(-maxY - dy0, 2 * H);
            long high = floorDiv(maxY - dy0, 2 * H);
            return Math.max(0, high - low + 1);
        }

        if (H == 0) {
            long y2 = dy0 * dy0;
            if (y2 > R2) return 0;
            long rem = R2 - y2;
            long maxX = isqrt(rem);
            long low = ceilDiv(-maxX - dx0, 2 * W);
            long high = floorDiv(maxX - dx0, 2 * W);
            return Math.max(0, high - low + 1);
        }

        long maxKAbs = isqrt(R2) / (2 * W) + 2;
        long kLow = ceilDiv(-isqrt(R2) - dx0, 2 * W);
        long kHigh = floorDiv(isqrt(R2) - dx0, 2 * W);

        for (long k = kLow; k <= kHigh; k++) {
            long x = dx0 + 2 * W * k;
            long x2 = x * x;
            if (x2 > R2) continue;
            long rem = R2 - x2;
            long maxY = isqrt(rem);
            long lLow = ceilDiv(-maxY - dy0, 2 * H);
            long lHigh = floorDiv(maxY - dy0, 2 * H);
            if (lHigh >= lLow) ans += (lHigh - lLow + 1);
        }
        return ans;
    }

    static long isqrt(long x) {
        long r = (long) Math.sqrt((double) x);
        while ((r + 1) > 0 && (r + 1) <= x / (r + 1)) r++;
        while (r > x / r) r--;
        return r;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        long w = fs.nextLong();
        long h = fs.nextLong();
        long p = fs.nextLong();
        long q = fs.nextLong();
        long x = fs.nextLong();
        long y = fs.nextLong();
        long v = fs.nextLong();
        long t = fs.nextLong();

        long R2 = v * t;
        R2 *= R2;

        long W = w;
        long H = h;

        // By unfolding reflections:
        // Count mirrored images of (p,q):
        // (2aw ± p, 2bh ± q)
        // reachable from (x,y) within radius vt.
        //
        // Equivalent four residue classes:
        // dx = sx*p - x  with sx in {+1,-1} interpreted as p or -p
        // but because image coordinates are 2kw ± p, offsets become:
        // p - x, -p - x, p - x with shifted k, etc.
        // A convenient complete set is:
        // ( p - x,  q - y)
        // ( p - x, -q - y)
        // (-p - x,  q - y)
        // (-p - x, -q - y)
        // with periods 2w, 2h.
        //
        // This counts each distinct direction/image exactly once.

        long[] dxs = {p - x, p - x, -p - x, -p - x};
        long[] dys = {q - y, -q - y, q - y, -q - y};

        long ans = 0;
        for (int i = 0; i < 4; i++) {
            ans += countForTarget(dxs[i], dys[i], W, H, R2);
        }

        System.out.println(ans);
    }
